package com.waseem.locationtracking.utils.helperimport android.animation.ValueAnimatorimport android.content.Contextimport android.graphics.Bitmapimport android.graphics.Canvasimport android.graphics.drawable.BitmapDrawableimport android.graphics.drawable.Drawableimport android.location.Geocoderimport android.location.Locationimport android.os.Handlerimport android.os.Looperimport android.util.Logimport android.view.animation.LinearInterpolatorimport androidx.annotation.DrawableResimport androidx.annotation.RawResimport androidx.core.content.ContextCompatimport com.google.android.gms.location.LocationCallbackimport com.google.android.gms.location.LocationResultimport com.google.android.gms.maps.CameraUpdateFactoryimport com.google.android.gms.maps.GoogleMapimport com.google.android.gms.maps.model.BitmapDescriptorimport com.google.android.gms.maps.model.BitmapDescriptorFactoryimport com.google.android.gms.maps.model.CameraPositionimport com.google.android.gms.maps.model.LatLngimport com.google.android.gms.maps.model.LatLngBoundsimport com.google.android.gms.maps.model.MapStyleOptionsimport com.google.android.gms.maps.model.Markerimport com.google.android.gms.maps.model.MarkerOptionsimport com.google.android.gms.maps.model.Polylineimport com.google.android.gms.maps.model.PolylineOptionsimport com.waseem.locationtracking.Rimport java.util.Localeimport kotlin.math.atan2import kotlin.math.cosimport kotlin.math.sinimport kotlin.math.sqrtclass MapManager {    var googleMap: GoogleMap? = null    private var currentMarker: Marker? = null    private var lastLocation: Location? = null    private var locationChangedCallback: LocationChangedCallback? = null    private lateinit var CAR_ICON: BitmapDescriptor    private var polyLine: Polyline? = null    private var destinationMarker: Marker? = null    private val width = 30.77f    private var latLngList: List<LatLng>? = null    private var bounds: LatLngBounds? = null    private val mapPadding = 70    private val aspectRatio = 1.545f    interface LocationChangedCallback {        fun onLocationChanged(location: Location)    }    fun setLocationChangedCallback(callback: LocationChangedCallback) {        locationChangedCallback = callback    }    fun setMap(context: Context, googleMap: GoogleMap) {        this.googleMap = googleMap        setCarIcon(context)    }    private fun addCurrentLocationMarker(location: Location) {        if (minimumDistanceTraveled(location)) {            Log.e("mapManager", "addCurrentLocationMarker: ")            // If the location hasn't changed significantly (e.g., within 10 meters), don't update the marker            return        }        googleMap?.let {            val latLng = LatLng(location.latitude, location.longitude)            if (currentMarker == null) {                // If there is no marker, add one                val markerOptions = MarkerOptions()                    .position(latLng)                    .title("Current Location")                    .icon(CAR_ICON)                    .rotation(                        getAdjustedBearing(                            location.latitude,                            location.longitude,                            lastLocation?.latitude,                            lastLocation?.longitude,                            it.cameraPosition.bearing                        )                    )                currentMarker = it.addMarker(markerOptions)            } else {                // If there is already a marker, animate it to the new position                animateMarker(currentMarker!!, latLng)                animateMarkerRotation(                    currentMarker!!,                    getAdjustedBearing(                        location.latitude,                        location.longitude,                        lastLocation?.latitude,                        lastLocation?.longitude,                        it.cameraPosition.bearing                    )                )            }            // Move and zoom the camera to the current location            if (latLngList == null) {                val cameraUpdate = CameraUpdateFactory.newLatLngZoom(latLng, 15f)                it.animateCamera(cameraUpdate)            }        }        // Update last known location        lastLocation = location    }    private fun addCurrentLocationMarkerWithMapRotation(location: Location) {        if (minimumDistanceTraveled(location)) {            Log.e("mapManager", "addCurrentLocationMarker: Location hasn't changed significantly")            return        }        googleMap?.let {            val latLng = LatLng(location.latitude, location.longitude)            // Calculate the car's bearing relative to the previous location            val newBearing = getAdjustedBearing(                location.latitude,                location.longitude,                lastLocation?.latitude,                lastLocation?.longitude,                it.cameraPosition.bearing            )            if (currentMarker == null) {                // If there is no marker, add one                val markerOptions = MarkerOptions()                    .position(latLng)                    .title("Current Location")                    .icon(CAR_ICON)                    .rotation(newBearing) // Optionally set initial rotation                currentMarker = it.addMarker(markerOptions)            } else {                // If there is already a marker, animate it to the new position                animateMarker(currentMarker!!, latLng)                // Optionally update the marker's rotation if needed                // animateMarkerRotation(currentMarker!!, newBearing)            }            // Update the camera's bearing to keep the car marker pointing upwards            val cameraUpdate = CameraUpdateFactory.newCameraPosition(                CameraPosition.Builder()                    .target(latLng)                    .zoom(it.cameraPosition.zoom)                    .bearing(newBearing) // Set the bearing to align with the car's direction                    .build()            )            it.animateCamera(cameraUpdate)            // Move and zoom the camera to the current location if needed            if (latLngList == null) {                val zoomUpdate = CameraUpdateFactory.newLatLngZoom(latLng, 15f)                it.animateCamera(zoomUpdate)            }        }        // Update last known location        lastLocation = location    }    val MINIMUM_DISTANCE = 5    fun minimumDistanceTraveled(location: Location): Boolean {//        return (lastLocation != null) && location.distanceTo(lastLocation!!) < MINIMUM_DISTANCE        return false    }    fun clearRoute() {        googleMap?.clear()        Log.d("MapManager", "clearRoute: Map clear")    }    private fun animateMarker(marker: Marker, toPosition: LatLng) {        val fromPosition = marker.position        val valueAnimator = ValueAnimator.ofFloat(0f, 1f)        valueAnimator.duration = 1000 // duration of the animation        valueAnimator.interpolator = LinearInterpolator()        valueAnimator.addUpdateListener { animation ->            val v = animation.animatedFraction            val newLatLng = LatLng(                fromPosition.latitude * (1 - v) + toPosition.latitude * v,                fromPosition.longitude * (1 - v) + toPosition.longitude * v            )            marker.position = newLatLng        }        valueAnimator.start()    }    private fun animateMarkerRotation(marker: Marker, toRotation: Float) {        val startRotation = marker.rotation        val shortestRotation = getShortestRotation(startRotation, toRotation)        val valueAnimator = ValueAnimator.ofFloat(startRotation, shortestRotation)        valueAnimator.duration = 1000 // duration of the animation        valueAnimator.interpolator = LinearInterpolator()        valueAnimator.addUpdateListener { animation ->            marker.rotation = animation.animatedValue as Float        }        valueAnimator.start()    }    private fun getShortestRotation(fromRotation: Float, toRotation: Float): Float {        val diff = (toRotation - fromRotation + 360) % 360        return if (diff > 180) {            fromRotation - (360 - diff)        } else {            fromRotation + diff        }    }    private fun applyCustomMapStyle(context: Context, @RawRes styleResId: Int) {        try {            val success = googleMap?.setMapStyle(                MapStyleOptions.loadRawResourceStyle(context, styleResId)            )            if (success == false) {                Log.e("MapManager", "Failed to apply map style")            }        } catch (e: Exception) {            Log.e("MapManager", "Error applying map style", e)        }    }    fun addCustomMarker(        context: Context,        latLng: LatLng,        @DrawableRes markerDrawable: Int,        title: String    ) {        googleMap?.let {            val markerOptions = MarkerOptions()                .position(latLng)                .title(title)                .icon(bitmapDescriptorFromVector(context, markerDrawable))            it.addMarker(markerOptions)        }    }    private fun bitmapDescriptorFromVector(        context: Context,        @DrawableRes vectorResId: Int    ): BitmapDescriptor? {        val vectorDrawable = ContextCompat.getDrawable(context, vectorResId)        vectorDrawable?.setBounds(            0,            0,            vectorDrawable.intrinsicWidth,            vectorDrawable.intrinsicHeight        )        val bitmap = Bitmap.createBitmap(            vectorDrawable!!.intrinsicWidth,            vectorDrawable.intrinsicHeight,            Bitmap.Config.ARGB_8888        )        val canvas = Canvas(bitmap)        vectorDrawable.draw(canvas)        return BitmapDescriptorFactory.fromBitmap(bitmap)    }    fun getAddressFromLocation(context: Context, location: Location): String {        val geocoder = Geocoder(context, Locale.getDefault())        var addressText = ""        try {            val addresses = geocoder.getFromLocation(location.latitude, location.longitude, 1)            if (!addresses.isNullOrEmpty()) {                val address = addresses[0]                val addressParts = mutableListOf<String>()                address.featureName?.let { addressParts.add(it) }                address.subLocality?.let { addressParts.add(it) }                address.locality?.let { addressParts.add(it) }                address.adminArea?.let { addressParts.add(it) }                address.countryName?.let { addressParts.add(it) }                addressText = addressParts.joinToString(", ")                Log.d(                    "MapManager",                    "Complete Address: $addressText\nLat: ${address.latitude}  Lng: ${address.longitude}"                )            } else {                Log.d("MapManager", "No address found for the given coordinates")            }        } catch (e: Exception) {            Log.e("MapManager", "Error getting address from location", e)        }        return addressText    }    val locationCallback = object : LocationCallback() {        override fun onLocationResult(locationResult: LocationResult) {            super.onLocationResult(locationResult)            locationResult.lastLocation?.let { location ->                Log.d("MapManager", "Location Changed: ${locationResult.lastLocation}, Provider: ${location.provider}")                locationChangedCallback?.onLocationChanged(location)            }        }    }    private fun animateCameraToPosition(latitude: Double, longitude: Double) {        googleMap?.let {            val cameraUpdate = CameraUpdateFactory.newLatLngZoom(LatLng(latitude, longitude), 15f)            Handler(Looper.getMainLooper()).postDelayed({                it.animateCamera(cameraUpdate)            }, 300) // Adjust delay as needed        } ?: Log.e("MSJLogs", "GoogleMap is not initialized")    }    private fun setCarIcon(context: Context) {        val drawableId = R.drawable.current_marker        CAR_ICON = BitmapDescriptorFactory.fromBitmap(            resizeBitmapWithAspectRatio(                context = context,                drawableId = drawableId,                baseSize = width,                aspectRatio = aspectRatio            )        )    }    private fun resizeBitmapWithAspectRatio(        context: Context,        drawableId: Int,        baseSize: Float, // This could be the width or height, whichever you prefer to base the size on        aspectRatio: Float,        isBaseWidth: Boolean = true // Flag to determine if baseSize is width or height    ): Bitmap {        val drawable = ContextCompat.getDrawable(context, drawableId) ?: throw IllegalArgumentException("Drawable not found")        val density = context.resources.displayMetrics.density        // Calculate dimensions based on aspect ratio        val widthPx: Int        val heightPx: Int        if (isBaseWidth) {            widthPx = (baseSize * density).toInt()            heightPx = (baseSize * aspectRatio * density).toInt()        } else {            heightPx = (baseSize * density).toInt()            widthPx = ((baseSize / aspectRatio) * density).toInt()        }        val bitmap = drawableToBitmap(drawable)        return Bitmap.createScaledBitmap(bitmap, widthPx, heightPx, false)    }    private fun getBitmapFromDrawable(context: Context, drawableId: Int): Bitmap {        val drawable = ContextCompat.getDrawable(context, drawableId)            ?: throw IllegalArgumentException("Drawable not found")        return drawableToBitmap(drawable)    }    private fun drawableToBitmap(drawable: Drawable): Bitmap {        if (drawable is BitmapDrawable) {            return drawable.bitmap        }        val bitmap = Bitmap.createBitmap(            drawable.intrinsicWidth,            drawable.intrinsicHeight,            Bitmap.Config.ARGB_8888        )        val canvas = Canvas(bitmap)        drawable.setBounds(0, 0, canvas.width, canvas.height)        drawable.draw(canvas)        return bitmap    }    fun drawRoute(latLngList: List<LatLng>, context: Context) {        // Remove all polylines from the map        polyLine?.remove()        destinationMarker?.remove()        this.latLngList = listOf()        Log.d("MapManager", "LatLng: $latLngList")        this.latLngList = latLngList        val builder = LatLngBounds.Builder()        for (latLng in latLngList) {            builder.include(latLng)        }        bounds = builder.build()        googleMap?.animateCamera(CameraUpdateFactory.newLatLngBounds(bounds!!, mapPadding))        val polyLineOptions = PolylineOptions()            .color(ContextCompat.getColor(context, R.color.route_color))            .width(10f)            .addAll(latLngList)        polyLine = googleMap?.addPolyline(polyLineOptions)        destinationMarker =            addOriginDestinationMarkerAndGet(latLngList[latLngList.size - 1], context)        destinationMarker?.setAnchor(0.5f, 0.5f)    }    private fun addOriginDestinationMarkerAndGet(latLng: LatLng, context: Context): Marker? {        return googleMap?.addMarker(            MarkerOptions().position(latLng).flat(true)                .icon(                    bitmapDescriptorFromVectorWithScaling(                        context,                        R.drawable.tracking_marker,                        1.0f                    )                ) // Set scaleFactor to 1.0f for no scaling        )    }    private fun bitmapDescriptorFromVectorWithScaling(        context: Context,        vectorResId: Int,        scaleFactor: Float    ): BitmapDescriptor {        val vectorDrawable: Drawable? = ContextCompat.getDrawable(context, vectorResId)        if (vectorDrawable == null) {            Log.e("MapManager", "Resource not found")            return BitmapDescriptorFactory.defaultMarker()        }        // Ensure the scale factor is 1.0f to keep the original size        val width = (vectorDrawable.intrinsicWidth * scaleFactor).toInt()        val height = (vectorDrawable.intrinsicHeight * scaleFactor).toInt()        vectorDrawable.setBounds(0, 0, width, height)        val bitmap: Bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)        val canvas = Canvas(bitmap)        vectorDrawable.draw(canvas)        return BitmapDescriptorFactory.fromBitmap(bitmap)    }    fun updateRoute(currentLocation: LatLng) {        latLngList?.let { latLngList ->            // Find the nearest point index on the route to the current location            val nearestPointIndex = findNearestPointIndex(currentLocation, latLngList)            // Update the polyline to show the route from the nearest point to the destination            polyLine?.points = latLngList.subList(nearestPointIndex, latLngList.size)            val builder = LatLngBounds.Builder()            for (latLng in latLngList) {                builder.include(latLng)            }            bounds = builder.build()//            googleMap?.animateCamera(CameraUpdateFactory.newLatLngBounds(bounds!!, mapPadding))        }    }    private fun findNearestPointIndex(currentLocation: LatLng, latLngList: List<LatLng>): Int {        var nearestPointIndex = 0        var smallestDistance = Float.MAX_VALUE        for (i in latLngList.indices) {            val distance = FloatArray(1)            Location.distanceBetween(                currentLocation.latitude,                currentLocation.longitude,                latLngList[i].latitude,                latLngList[i].longitude,                distance            )            if (distance[0] < smallestDistance) {                smallestDistance = distance[0]                nearestPointIndex = i            }        }        return nearestPointIndex    }    private fun getBearing(        startLat: Double,        startLng: Double,        endLat: Double?,        endLng: Double?    ): Float {        if (endLat == null || endLng == null) return 0f        val startPoint = Location("startPoint").apply {            latitude = startLat            longitude = startLng        }        val endPoint = Location("endPoint").apply {            latitude = endLat            longitude = endLng        }        return startPoint.bearingTo(endPoint)    }    fun getDisplacementFromLatLngInMeters(        lat: Double, lng: Double, newLat: Double, newLng: Double    ): Double {        val R = 6371 // Radius of the earth in km        val dLat = Math.toRadians(newLat - lat)        val dLon = Math.toRadians(newLng - lng)        val a =            sin(dLat / 2) * sin(dLat / 2) + cos(Math.toRadians(lat)) * cos(Math.toRadians(newLat)) * sin(                dLon / 2            ) * sin(dLon / 2)        val c = 2 * atan2(sqrt(a), sqrt(1 - a))        val displacement = R * c * 1000        Log.d("MapManager", displacement.toString())        return displacement    }    private fun getAdjustedBearing(        startLat: Double,        startLng: Double,        endLat: Double?,        endLng: Double?,        mapBearing: Float    ): Float {        val bearing = getBearing(startLat, startLng, endLat, endLng)        return (bearing - mapBearing + 360) % 360    }    fun updateGoogleMapWithCurrentLocation(location: Location) {        addCurrentLocationMarker(location)        updateRoute(LatLng(location.latitude, location.longitude))    }}